import math

def count_divisors(n):
    # Initialize result
    count = 0
    i = 1
    while i <= math.sqrt(n):
        # if i is a factor of n
        if n % i == 0:
            # if both divisors are same then add one
            if n/i == i:
                if i % 3 == 0:
                    count += 1
            else:
                # else add 2
                if i % 3 == 0:
                    count += 1
                if (n/i) % 3 == 0:
                    count += 1
        i += 1
    return count

n = 3240
print(count_divisors(n))

