def solve():
    from itertools import permutations

    scores = [71, 76, 80, 82, 91]

    for perm in permutations(scores):
        total = 0
        count = 0
        all_integers = True
        for score in perm:
            total += score
            count += 1
            if total % count != 0:
                all_integers = False
                break
        if all_integers:
            return perm[-1]
